style.css:
@-moz-document domain("mql5.com") {
/* MQL5.com Modern Dark Theme */

/* Main Background Colors */
body {
    background-color: #1a1a1a !important;
    color: #e0e0e0 !important;
}

/* Header */
.head {
    background-color: #0d0d0d !important;
    border-bottom: 1px solid #2a2a2a !important;
}

.head__logo {
    filter: brightness(0.9) !important;
}

/* Main Menu */
.main-menu {
    background-color: #0d0d0d !important;
}

.main-menu__top-level a,
.main-menu__second-level a {
    color: #e0e0e0 !important;
}

.main-menu__top-level a:hover,
.main-menu__second-level a:hover {
    color: #4a9eff !important;
}

/* Search Bar */
.header-search {
    background-color: #2a2a2a !important;
}

.header-search__input input {
    background-color: #2a2a2a !important;
    color: #e0e0e0 !important;
    border: 1px solid #3a3a3a !important;
}

.header-search__placeholder {
    color: #808080 !important;
}

/* Main Content Area - Chat/Discussion */
.body,
article.body {
    background-color: #1f1f1f !important;
    color: #e0e0e0 !important;
}

/* Chat/Message Area - RGB(31,31,31) */
.content-with-sidebar,
.profile-edit-area,
form.profileEditEx {
    background-color: rgb(31, 31, 31) !important;
    color: #e0e0e0 !important;
}

/* Sidebar */
.left-sidebar {
    background-color: #1a1a1a !important;
    border-right: 1px solid #2a2a2a !important;
}

.tree-menu {
    background-color: #1a1a1a !important;
}

.tree-menu__link {
    color: #b0b0b0 !important;
}

.tree-menu__link:hover {
    background-color: #2a2a2a !important;
    color: #e0e0e0 !important;
}

.tree-menu__item_selected .tree-menu__link {
    background-color: #2a2a2a !important;
    color: #4a9eff !important;
}

/* Profile Header */
.profile-header,
.top-band {
    background-color: #1a1a1a !important;
    border-bottom: 1px solid #2a2a2a !important;
}

.profileHeaderTitle {
    color: #e0e0e0 !important;
}

/* Sub Commands */
.profile-sub-commands {
    background-color: #1a1a1a !important;
}

.profile-sub-commands__item a {
    color: #b0b0b0 !important;
}

.profile-sub-commands__item:hover a,
.profile-sub-commands__item_selected a {
    color: #4a9eff !important;
}

/* Input Fields */
input[type="text"],
input[type="email"],
input[type="password"],
textarea,
select {
    background-color: #2a2a2a !important;
    color: #e0e0e0 !important;
    border: 1px solid #3a3a3a !important;
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="password"]:focus,
textarea:focus,
select:focus {
    border-color: #4a9eff !important;
    background-color: #2f2f2f !important;
}

input.input {
    background-color: #2a2a2a !important;
    color: #e0e0e0 !important;
}

input[disabled] {
    background-color: #1f1f1f !important;
    color: #707070 !important;
}

/* Buttons */
input[type="submit"],
.buttonActive,
.button,
button {
    background-color: #4a9eff !important;
    color: #ffffff !important;
    border: none !important;
}

input[type="submit"]:hover,
.buttonActive:hover,
.button:hover,
button:hover {
    background-color: #3a8eef !important;
}

/* Tabs */
.tab_menu {
    background-color: #1a1a1a !important;
    border-bottom: 1px solid #2a2a2a !important;
}

.tab_item {
    background-color: #2a2a2a !important;
}

.tab_item:hover,
.tab_item.selected {
    background-color: rgb(31, 31, 31) !important;
    border-bottom: 2px solid #4a9eff !important;
}

.tab_item span {
    color: #b0b0b0 !important;
}

.tab_item.selected span {
    color: #e0e0e0 !important;
}

.tab_content {
    background-color: rgb(31, 31, 31) !important;
}

/* Textarea specific styling */
textarea {
    background-color: #2a2a2a !important;
    color: #e0e0e0 !important;
}

/* Lines and Separators */
.midLine {
    background-color: #2a2a2a !important;
    border-color: #2a2a2a !important;
}

/* Links */
a {
    color: #4a9eff !important;
}

a:hover {
    color: #5aafff !important;
}

/* Notification Toolbar */
.notifications-toolbar {
    background-color: #0d0d0d !important;
}

.link-notify {
    color: #e0e0e0 !important;
}

.link-notify:hover {
    background-color: #2a2a2a !important;
}

/* User Link Menu */
.user-link-menu {
    background-color: #1a1a1a !important;
    border: 1px solid #2a2a2a !important;
}

.user-link-menu__item a {
    color: #b0b0b0 !important;
}

.user-link-menu__item:hover {
    background-color: #2a2a2a !important;
}

/* Language Menu */
.lang-menu {
    background-color: #1a1a1a !important;
}

.lang-menu__list-item a {
    color: #b0b0b0 !important;
}

.lang-menu__list-item:hover a {
    background-color: #2a2a2a !important;
    color: #e0e0e0 !important;
}

.lang-menu__list-item_selected a {
    background-color: #2a2a2a !important;
    color: #4a9eff !important;
}

/* Footer */
footer,
.footer {
    background-color: #0d0d0d !important;
    border-top: 1px solid #2a2a2a !important;
    color: #808080 !important;
}

.footer a {
    color: #4a9eff !important;
}

.footer__product-name {
    color: #e0e0e0 !important;
}

/* Profile Edit Area */
.profile-edit-area__item {
    border-bottom: 1px solid #2a2a2a !important;
}

.profile-edit-area__item label {
    color: #b0b0b0 !important;
}

/* Icons - Invert for visibility */
.icons-ux,
.icons-profile,
.notify-icon {
    filter: invert(0.9) !important;
}

/* Cover/Overlay */
.cover {
    background-color: #1a1a1a !important;
}

/* Shadow Layer */
.shadow-layer {
    background-color: rgba(0, 0, 0, 0.8) !important;
}

/* Scrollbars */
::-webkit-scrollbar {
    width: 12px;
    height: 12px;
}

::-webkit-scrollbar-track {
    background: #1a1a1a;
}

::-webkit-scrollbar-thumb {
    background: #3a3a3a;
    border-radius: 6px;
}

::-webkit-scrollbar-thumb:hover {
    background: #4a4a4a;
}

/* Additional UI Elements */
.inputWrapper {
    background-color: rgb(31, 31, 31) !important;
}

/* Group Menu */
.group-menu {
    background-color: #0d0d0d !important;
}

/* Block with Sidebar */
.block-with-sidebar {
    background-color: #1a1a1a !important;
}

/* About Me Section */
.aboutMe {
    color: #4a9eff !important;
}

/* Arrow Icons */
.arrowUp,
.arrowDown {
    filter: invert(0.9) !important;
}

/* Counters */
.tree-menu__counter,
.user-link-menu__counter {
    background-color: #4a9eff !important;
    color: #ffffff !important;
}

/* Profile Toolbar */
.profileToolbar {
    background-color: #0d0d0d !important;
}

.userlink {
    color: #e0e0e0 !important;
}

.userlink:hover {
    background-color: #2a2a2a !important;
}

/* Verification Badge */
.icons-ux_shield {
    filter: invert(0) hue-rotate(180deg) !important;
}

/* Left Sidebar Selector */
.left-sidebar__selector {
    background-color: #1a1a1a !important;
    color: #e0e0e0 !important;
}

/* Additional Contrast Adjustments */
h1, h2, h3, h4, h5, h6 {
    color: #e0e0e0 !important;
}

p {
    color: #d0d0d0 !important;
}

/* Ensure proper contrast for all text */
* {
    color: inherit;
}

body * {
    border-color: #2a2a2a !important;
  }
}
